// Query current break position
void *current_break = sbrk(0);

// Allocate 1024 bytes (previous break is returned)
intptr_t alloc_size = 1024;
void *allocation_start = sbrk(alloc_size);

// Check for sbrk() failure
if (allocation_start == (void*)-1) {
    // Handle error
}

// Calculate explicit target address
void *new_addr = current_break + 2048;

// Set break point explicitly using brk()
if (brk(new_addr) == 0) {
    // Success: data segment end is now new_addr
}

// Deallocate all memory (resetting break)
brk(current_break);
